import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.BDDMockito.given;
import static org.mockito.BDDMockito.then;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;

import java.time.Instant;
import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.graphql.test.autoconfigure.GraphQlTest;
import org.springframework.context.annotation.Import;
import org.springframework.data.domain.KeysetScrollPosition;
import org.springframework.data.domain.Limit;
import org.springframework.data.domain.ScrollPosition;
import org.springframework.data.domain.Sort;
import org.springframework.data.domain.Window;
import org.springframework.graphql.execution.ErrorType;
import org.springframework.graphql.test.tester.GraphQlTester;
import org.springframework.test.context.bean.override.mockito.MockitoBean;

// A slice: the schema, the controller and the exception resolver, no database.
@GraphQlTest(StoreController.class)
@Import(StoreExceptionResolver.class)
class StoreControllerTests {

    @Autowired
    GraphQlTester graphQlTester;

    @MockitoBean OrderRepository orders;
    @MockitoBean OrderLineRepository lines;
    @MockitoBean CustomerRepository customers;
    @MockitoBean ItemRepository items;
    @MockitoBean OrderService service;

    @Test
    void returnsTheFieldsAskedFor() {
        given(orders.findById(1L)).willReturn(
                Optional.of(new Order(1L, 3_000, Instant.parse("2026-09-01T10:00:00Z"))));

        graphQlTester.document("{ order(id: 1) { status total } }")
                .execute()
                .path("order.status").entity(String.class).isEqualTo("PLACED")
                .path("order.total").entity(Integer.class).isEqualTo(3000);
    }

    @Test
    void aMissingOrderIsNotFound() {
        given(orders.findById(999L)).willReturn(Optional.empty());

        graphQlTester.document("{ order(id: 999) { id } }")
                .execute()
                .errors()
                .expect(error -> error.getErrorType() == ErrorType.NOT_FOUND);
    }

    @Test
    void orderCountComesFromOneQueryForAllCustomersInTheResponse() {
        Customer ada = new Customer(1L, "Ada", "ada@example.com", "GOLD");
        Customer grace = new Customer(2L, "Grace", "grace@example.com", "SILVER");
        List<Order> page = List.of(order(1L, 1_000), order(2L, 2_000), order(1L, 3_000));
        given(orders.findBy(any(ScrollPosition.class), any(Limit.class), any(Sort.class)))
                .willReturn(keysetWindow(page, false));
        given(customers.findAllById(any())).willReturn(List.of(ada, grace));
        given(orders.countByCustomerIdIn(any())).willReturn(List.of(
                new CustomerOrderCount(1L, 12), new CustomerOrderCount(2L, 7)));

        graphQlTester.document("""
                { orders(first: 3) { edges { node { customer { id orderCount } } } } }
                """)
                .execute()
                .path("orders.edges[0].node.customer.orderCount").entity(Integer.class).isEqualTo(12)
                .path("orders.edges[1].node.customer.orderCount").entity(Integer.class).isEqualTo(7)
                .path("orders.edges[2].node.customer.orderCount").entity(Integer.class).isEqualTo(12);

        @SuppressWarnings("unchecked")
        ArgumentCaptor<Collection<Long>> ids = ArgumentCaptor.forClass(Collection.class);
        then(orders).should(times(1)).countByCustomerIdIn(ids.capture());
        assertThat(ids.getValue()).containsExactlyInAnyOrder(1L, 2L);
    }

    @Test
    void aCustomerWithoutOrdersHasAnOrderCountOfZero() {
        given(orders.findById(5L)).willReturn(Optional.of(order(3L, 500)));
        given(customers.findAllById(any())).willReturn(
                List.of(new Customer(3L, "Linus", "linus@example.com", "BRONZE")));
        given(orders.countByCustomerIdIn(any())).willReturn(List.of());

        graphQlTester.document("{ order(id: 5) { customer { orderCount } } }")
                .execute()
                .path("order.customer.orderCount").entity(Integer.class).isEqualTo(0);
    }

    @Test
    void customerOrdersReturnsTheFirstPageForThatCustomer() {
        given(customers.existsById(2L)).willReturn(true);
        List<Order> page = List.of(order(2L, 1_000), order(2L, 2_000), order(2L, 3_000));
        given(orders.findByCustomerId(eq(2L), any(ScrollPosition.class), any(Limit.class),
                any(Sort.class))).willReturn(keysetWindow(page, true));

        graphQlTester.document("""
                { customerOrders(customerId: 2, first: 3) {
                    edges { node { amount } }
                    pageInfo { hasNextPage endCursor }
                } }
                """)
                .execute()
                .path("customerOrders.edges[*].node.amount").entityList(Integer.class)
                        .containsExactly(1000, 2000, 3000)
                .path("customerOrders.pageInfo.hasNextPage").entity(Boolean.class).isEqualTo(true)
                .path("customerOrders.pageInfo.endCursor").entity(String.class).satisfies(
                        cursor -> assertThat(cursor).isNotBlank());

        ArgumentCaptor<ScrollPosition> position = ArgumentCaptor.forClass(ScrollPosition.class);
        then(orders).should().findByCustomerId(eq(2L), position.capture(), eq(Limit.of(3)),
                eq(Sort.by("id")));
        assertThat(position.getValue().isInitial()).isTrue();
    }

    @Test
    void customerOrdersDefaultsToTenPerPage() {
        given(customers.existsById(2L)).willReturn(true);
        given(orders.findByCustomerId(eq(2L), any(ScrollPosition.class), any(Limit.class),
                any(Sort.class))).willReturn(keysetWindow(List.of(), false));

        graphQlTester.document("{ customerOrders(customerId: 2) { edges { node { id } } } }")
                .execute()
                .path("customerOrders.edges").entityList(Object.class).hasSize(0);

        then(orders).should().findByCustomerId(eq(2L), any(ScrollPosition.class),
                eq(Limit.of(10)), eq(Sort.by("id")));
    }

    @Test
    void customerOrdersContinuesFromTheCursor() {
        given(customers.existsById(2L)).willReturn(true);
        List<Order> page = List.of(order(2L, 1_000), order(2L, 2_000), order(2L, 3_000));
        given(orders.findByCustomerId(eq(2L), any(ScrollPosition.class), any(Limit.class),
                any(Sort.class))).willReturn(keysetWindow(page, true));

        String endCursor = graphQlTester.document(
                        "{ customerOrders(customerId: 2, first: 3) { pageInfo { endCursor } } }")
                .execute()
                .path("customerOrders.pageInfo.endCursor").entity(String.class).get();

        graphQlTester.document("""
                query($after: String) {
                    customerOrders(customerId: 2, first: 3, after: $after) { edges { node { id } } }
                }
                """)
                .variable("after", endCursor)
                .execute()
                .path("customerOrders.edges").entityList(Object.class).hasSize(3);

        ArgumentCaptor<ScrollPosition> position = ArgumentCaptor.forClass(ScrollPosition.class);
        then(orders).should(times(2)).findByCustomerId(eq(2L), position.capture(),
                eq(Limit.of(3)), eq(Sort.by("id")));
        ScrollPosition second = position.getAllValues().get(1);
        assertThat(second).isInstanceOf(KeysetScrollPosition.class);
        assertThat(second.isInitial()).isFalse();
        // The cursor of the third row carries its keyset, so the next page starts after it.
        assertThat(String.valueOf(((KeysetScrollPosition) second).getKeys().get("id")))
                .isEqualTo("3");
    }

    @Test
    void customerOrdersForAnUnknownCustomerIsNotFound() {
        given(customers.existsById(42L)).willReturn(false);

        graphQlTester.document("{ customerOrders(customerId: 42) { edges { node { id } } } }")
                .execute()
                .errors()
                .expect(error -> error.getErrorType() == ErrorType.NOT_FOUND
                        && "No customer 42".equals(error.getMessage()))
                .verify()
                .path("customerOrders").pathDoesNotExist();

        then(orders).should(never()).findByCustomerId(anyLong(), any(), any(), any());
    }

    private static Order order(Long customerId, long total) {
        return new Order(customerId, total, Instant.parse("2026-09-01T10:00:00Z"));
    }

    // A window whose cursors are keyset positions on id, as the real repository
    // would produce; test orders have no generated id, so the row number stands in.
    private static Window<Order> keysetWindow(List<Order> page, boolean hasNext) {
        return Window.from(page, i -> ScrollPosition.forward(Map.of("id", (long) i + 1)), hasNext);
    }
}
